INSERT INTO `redeem_codes` VALUES (1,'LINISWARA-SD2026','Paket Belajar & Bank Soal Akbar SD/MI Lengkap Kelas 1–6 (90 Hari)','Membuka seluruh video SD Kelas 1–6, 6 paket per kelas, dan Bank Soal Akbar SD/MI (60 Soal B/S).',90,500,11,1,'2026-11-25 10:54:45'),(2,'LINISWARA-SMP2026','Paket Belajar & Bank Soal Akbar TKA SMP/MTs Kelas 7–9 (90 Hari)','Membuka seluruh video SMP Kelas 7–9, paket per kelas, dan Bank Soal Akbar SMP/MTs (60 Soal B/S).',90,500,19,1,'2026-11-25 10:54:45'),(3,'LINISWARA-TKA2025','Paket Smart Steps TKA & Bank Soal Akbar SMA/MA MIPA & IPS (90 Hari)','Membuka seluruh video SMA Kelas 10–12 MIPA/IPS, 6 paket peminatan, dan Bank Soal Akbar SMA/MA (80 Soal B/S).',90,500,24,1,'2026-11-25 10:54:45'),(4,'SMARTSTEPS-SMK','Paket Kejuruan & Bank Soal Akbar SMK/MAK Semua Jurusan (60 Hari)','Membuka seluruh video kejuruan SMK, paket Teknologi/Bisnis, dan Bank Soal Akbar SMK/MAK (100 Soal B/S).',60,250,9,1,'2026-11-25 10:54:46'),(5,'MGMP-JATENG25','Program Kolaborasi Guru MGMP Semua Jenjang (120 Hari)','Voucher resmi guru & sekolah mitra MGMP untuk membuka seluruh jenjang SD–SMK beserta Bank Soal Akbar.',120,1000,42,1,'2026-11-25 10:54:46'),(6,'BUKU-SD-KELAS1','Paket Buku Cetak SD/MI Khusus Kelas 1 (90 Hari)','Voucher buku cetak pendamping SD/MI Kelas 1 (Fase A).',90,300,4,1,'2026-11-25 14:07:36'),(7,'BUKU-SD-KELAS2','Paket Buku Cetak SD/MI Khusus Kelas 2 (90 Hari)','Voucher buku cetak pendamping SD/MI Kelas 2 (Fase A).',90,300,3,1,'2026-11-25 14:07:36'),(8,'LINISWARA-GIVEAWAY1','Paket Buku Cetak SD/MI Khusus Kelas 3 (90 Hari)','Voucher buku cetak pendamping SD/MI Kelas 3 (Fase B).',90,1,1,1,'2026-11-25 13:30:20'),(9,'SMK','Paket Buku Cetak SD/MI Khusus Kelas 4 (90 Hari)','Voucher buku cetak IPAS & Numerasi SD/MI Kelas 4 (Fase B).',90,100,1,1,'2026-11-25 13:49:48'),(10,'BUKU-SD-KELAS5','Paket Buku Cetak SD/MI Khusus Kelas 5 (90 Hari)','Voucher buku cetak Pecahan & IPAS SD/MI Kelas 5 (Fase C).',90,300,7,1,'2026-11-25 14:07:36'),(11,'BUKU-SD-KELAS6','Paket Buku Cetak SD/MI Khusus Kelas 6 (90 Hari)','Voucher buku cetak AKM & Numerasi SD/MI Kelas 6 (Fase C).',90,300,8,1,'2026-11-25 14:07:36'),(12,'BUKU-SMP-KELAS7','Paket Buku Cetak SMP/MTs Khusus Kelas 7 (90 Hari)','Voucher buku Matematika & Aljabar SMP/MTs Kelas 7.',90,300,5,1,'2026-11-25 14:07:36'),(13,'BUKU-SMP-KELAS8','Paket Buku Cetak SMP/MTs Khusus Kelas 8 (90 Hari)','Voucher buku IPA & Teks Berita SMP/MTs Kelas 8.',90,300,4,1,'2026-11-25 14:07:36'),(14,'BUKU-SMP-KELAS9','Paket Buku Cetak TKA SMP/MTs Khusus Kelas 9 (90 Hari)','Voucher intensif persiapan TKA & Koding AI SMP/MTs Kelas 9.',90,300,9,1,'2026-11-25 14:07:36'),(15,'BUKU-SMA-MIPA','Paket Buku Cetak SMA/MA Kelas 10–12 Peminatan MIPA (90 Hari)','Voucher khusus peminatan MIPA SMA/MA (Fisika, Kimia, Biologi, Matematika).',90,300,10,1,'2026-11-25 14:07:36'),(16,'BUKU-SMA-IPS','Paket Buku Cetak SMA/MA Kelas 10–12 Peminatan IPS & Bahasa (90 Hari)','Voucher khusus peminatan IPS & Bahasa SMA/MA (Ekonomi, Geografi, Sosiologi).',90,300,7,1,'2026-11-25 14:07:36'),(17,'BUKU-SMK-TEKNIK','Paket Buku Cetak SMK/MAK Kelas 10–12 Jurusan Teknologi & IT (90 Hari)','Voucher khusus kejuruan TJKT, RPL, Koding AI, dan Teknik Otomotif SMK.',90,300,6,1,'2026-11-25 14:07:36'),(18,'BUKU-SMK-BISNIS','Paket Buku Cetak SMK/MAK Kelas 10–12 Jurusan Bisnis & Pariwisata (90 Hari)','Voucher khusus kejuruan Akuntansi, Bisnis Digital, KIK, Perhotelan & Kuliner SMK.',90,300,5,1,'2026-11-25 14:07:36');
