  `correct_statements` int NOT NULL,
  `total_statements` int NOT NULL,
  `perfect_questions` int NOT NULL,
  `answers_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_seconds` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `package_id` (`package_id`),
  CONSTRAINT `tryout_attempts_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `tryout_attempts_ibfk_2` FOREIGN KEY (`package_id`) REFERENCES `tryout_packages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
