INSERT INTO `tryout_packages` VALUES (1,'tryout-sd-mi-literasi-numerasi','Tryout Diagnostik Gratis SD/MI (Kelas 1–6) — Literasi & Numerasi Dasar','SD/MI','Kelas 1–6 (Diagnostik Gratis) • Bahasa Indonesia, Matematika & IPAS','Uji coba gratis untuk seluruh peserta terdaftar! 10 soal pilihan ganda kompleks (3 pernyataan Benar/Salah per soal) ramah siswa SD/MI.',25,10,0),(2,'tryout-smp-mts-matematika-koding','Tryout Diagnostik Gratis SMP/MTs (Kelas 7–9) — Literasi & Penalaran Fase D','SMP/MTs','Kelas 7–9 (Diagnostik Gratis) • Matematika, IPS, Bahasa & Koding AI','Diagnostic test gratis bagi akun baru SMP/MTs. Simulasi 10 soal × 3 pernyataan B/S sebelum membuka paket Kelas 7, 8, 9 & Bank Soal Akbar.',30,10,0),(3,'smart-steps-tka-sma-ma','Tryout Diagnostik Gratis SMA/MA (Kelas 10–12) — TPS, Literasi & Inggris','SMA/MA','Kelas 10–12 (Diagnostik Gratis) • TPS, Literasi Bahasa & Numerasi','Uji coba gratis seri SMART STEPS: TKA untuk jenjang SMA/MA (10 soal × 3 B/S) dengan pembahasan langsung tiap pernyataan.',30,10,0),(4,'smart-steps-tka-smk-mak','Tryout Diagnostik Gratis SMK/MAK (Kelas 10–12) — KIK & Literasi Vokasi','SMK/MAK','Kelas 10–12 (Diagnostik Gratis) • KIK, Numerasi & Studi Kasus Vokasi','Uji coba gratis pelajar SMK/MAK seluruh jurusan (10 soal × 3 B/S) meliputi KIK usaha, keselamatan kerja, dan literasi industri.',30,10,0),(5,'lanjutan-sd-kelas-1','Paket SD/MI Kelas 1 (Fase A) — Membaca Permulaan & Berhitung','SD/MI','Kelas 1 (Fase A) • Bahasa Indonesia & Penjumlahan Pengurangan','Khusus siswa SD/MI Kelas 1 (Kode BUKU-SD-KELAS1 atau LINISWARA-SD2026). 10 soal cerita bergambar ramah anak usia kelas 1.',25,10,1),(6,'lanjutan-sd-kelas-2','Paket SD/MI Kelas 2 (Fase A) — Perkalian Dasar & Nilai Uang Rupiah','SD/MI','Kelas 2 (Fase A) • Matematika Berhitung & Literasi Lingkungan','Khusus siswa SD/MI Kelas 2 (Kode BUKU-SD-KELAS2 atau LINISWARA-SD2026). Melatih perkalian sederhana dan transaksi uang koperasi sekolah.',25,10,1),(7,'lanjutan-sd-kelas-3','Paket SD/MI Kelas 3 (Fase B) — Satuan Panjang, Pecahan & Siklus Hidup','SD/MI','Kelas 3 (Fase B) • IPAS, Meter-Sentimeter & Pecahan Dasar','Khusus siswa SD/MI Kelas 3 (Kode BUKU-SD-KELAS3 atau LINISWARA-SD2026). Memuat soal satuan panjang meter/cm, pecahan kue, dan metamorfosis.',25,10,1),(8,'lanjutan-sd-kelas-4','Paket SD/MI Kelas 4 (Fase B) — Luas Keliling & Bagian Tubuh Tumbuhan','SD/MI','Kelas 4 (Fase B) • Matematika Geometri & IPAS Tumbuhan','Khusus siswa SD/MI Kelas 4 (Kode BUKU-SD-KELAS4 atau LINISWARA-SD2026). Soal luas/keliling persegi panjang serta fungsi akar & daun fotosintesis.',30,10,1),(9,'lanjutan-sd-kelas-5','Paket SD/MI Kelas 5 (Fase C) — Volume Balok, Persen & Rantai Makanan','SD/MI','Kelas 5 (Fase C) • Matematika Volume/Persen & Ekosistem IPAS','Khusus siswa SD/MI Kelas 5 (Kode BUKU-SD-KELAS5 atau LINISWARA-SD2026). Melatih hitung liter akuarium, diskon 20%, dan rantai makanan sawah.',30,10,1),(10,'lanjutan-sd-kelas-6','Paket SD/MI Kelas 6 (Fase C) — Persiapan AKM Numerasi, Kecepatan & Tata Surya','SD/MI','Kelas 6 (Fase C) • AKM Numerasi, Kecepatan & IPA Tata Surya','Khusus siswa SD/MI Kelas 6 (Kode BUKU-SD-KELAS6 atau LINISWARA-SD2026). Fokus soal jarak-waktu, rata-rata data nilai, dan tata surya.',30,10,1),(11,'lanjutan-smp-kelas-7','Paket SMP/MTs Kelas 7 (Fase D) — Aljabar PLSV, Himpunan & Aritmetika Sosial','SMP/MTs','Kelas 7 (Fase D) • Matematika Aljabar, Bunga Tabungan & IPA Kalor','Khusus SMP/MTs Kelas 7 (Kode BUKU-SMP-KELAS7 atau LINISWARA-SMP2026). Soal persamaan linear, diagram Venn, suhu kalor, dan teks deskripsi.',30,10,1),(12,'lanjutan-smp-kelas-8','Paket SMP/MTs Kelas 8 (Fase D) — Pythagoras, Pencernaan & Teks Berita','SMP/MTs','Kelas 8 (Fase D) • Pythagoras, Sistem Pencernaan & Bahasa 5W+1H','Khusus SMP/MTs Kelas 8 (Kode BUKU-SMP-KELAS8 atau LINISWARA-SMP2026). Menguji teorema Pythagoras, enzim pencernaan, dan berita 5W+1H.',30,10,1),(13,'lanjutan-smp-kelas-9','Paket SMP/MTs Kelas 9 — Persiapan TKA, Ekspor IPS & Koding AI','SMP/MTs','Kelas 9 (Persiapan TKA) • Peluang, Ekspor-Impor & Koding AI','Khusus SMP/MTs Kelas 9 (Kode BUKU-SMP-KELAS9 atau LINISWARA-SMP2026). Simulasi TKA menghadapi ujian akhir SMP, logika AI, dan peluang.',35,10,1),(14,'lanjutan-sma-kelas-10-mipa','Paket SMA/MA Kelas 10 Peminatan MIPA — Hukum Newton, Kimia & Fungsi','SMA/MA','Kelas 10 • Peminatan MIPA (Matematika, Fisika Newton & Kimia Dasar)','Paket SMA/MA Kelas 10 jalur Saintek/MIPA (Kode BUKU-SMA-MIPA atau LINISWARA-TKA2025). 10 soal analitik × 3 pernyataan B/S.',35,10,1),(15,'lanjutan-sma-kelas-10-ips','Paket SMA/MA Kelas 10 Peminatan IPS — Permintaan, SIG & Sosiologi','SMA/MA','Kelas 10 • Peminatan IPS & Bahasa (Ekonomi Mikro, Geografi & Sosiologi)','Paket SMA/MA Kelas 10 jalur Soshum/IPS (Kode BUKU-SMA-IPS atau LINISWARA-TKA2025). Menguji kurva ekonomi, dasar SIG, dan mobilitas sosial.',35,10,1),(16,'lanjutan-sma-kelas-11-mipa','Paket SMA/MA Kelas 11 Peminatan MIPA — Turunan, Laju Reaksi & Biologi','SMA/MA','Kelas 11 • Peminatan MIPA (Kalkulus Turunan, Katalis & Mitosis)','Paket SMA/MA Kelas 11 jalur MIPA (Kode BUKU-SMA-MIPA atau LINISWARA-TKA2025). Soal optimasi fungsi kuadrat, laju reaksi kimia, dan biologi sel.',35,10,1),(17,'lanjutan-sma-kelas-11-ips','Paket SMA/MA Kelas 11 Peminatan IPS — Kebijakan Moneter, Demografi & Sejarah','SMA/MA','Kelas 11 • Peminatan IPS & Bahasa (Bank Sentral, Demografi & Heuristik)','Paket SMA/MA Kelas 11 jalur IPS (Kode BUKU-SMA-IPS atau LINISWARA-TKA2025). Soal inflasi/moneter BI, bonus demografi, dan metode sejarah.',35,10,1),(18,'lanjutan-sma-kelas-12-mipa','Paket SMA/MA Kelas 12 Peminatan MIPA — Intensif TKA Saintek & Genetika','SMA/MA','Kelas 12 (TKA) • Peminatan MIPA (Genetika Mendel, Fisika & Eksponensial)','Simulasi akhir Kelas 12 jalur MIPA (Kode BUKU-SMA-MIPA atau LINISWARA-TKA2025) berbasis standar TKA & SNBT Saintek.',35,10,1),(19,'lanjutan-sma-kelas-12-ips','Paket SMA/MA Kelas 12 Peminatan IPS — Intensif TKA Soshum & Literasi SNBT','SMA/MA','Kelas 12 (TKA) • Peminatan IPS & Bahasa (Silogisme SNBT, SIG & Ekonomi)','Simulasi akhir Kelas 12 jalur IPS & Bahasa (Kode BUKU-SMA-IPS atau LINISWARA-TKA2025) menghadapi TKA & SNBT Soshum.',35,10,1),(20,'lanjutan-smk-teknologi-it','Paket SMK/MAK Kelas 10–12 Jurusan Teknologi & IT — TJKT, RPL & Otomotif','SMK/MAK','Kelas 10–12 • Jurusan Teknologi & IT (TJKT, RPL, Koding AI, Otomotif)','Paket kejuruan teknologi SMK/MAK (Kode BUKU-SMK-TEKNIK atau SMARTSTEPS-SMK). Subnetting IPv4, SQL Injection, EFI otomotif, dan Hukum Ohm LED.',35,10,1),(21,'lanjutan-smk-bisnis-pariwisata','Paket SMK/MAK Kelas 10–12 Jurusan Bisnis & Pariwisata — Akuntansi & Kuliner','SMK/MAK','Kelas 10–12 • Jurusan Bisnis & Pariwisata (Akuntansi, Pemasaran, Perhotelan)','Paket kejuruan bisnis & pariwisata SMK/MAK (Kode BUKU-SMK-BISNIS atau SMARTSTEPS-SMK). BEP usaha, akuntansi, ROAS iklan, guest folio, dan HACCP.',35,10,1),(22,'bank-soal-akbar-buku-sd-mi-60','Bank Soal Akbar Buku Cetak SD/MI (60 Soal Komprehensif Kelas 1–6)','SD/MI','Bank Soal Akbar Buku (Kelas 1–6) • 60 Soal Literasi, Numerasi & IPAS','Paket spesial pembeli buku cetak SD/MI (Kode LINISWARA-SD2026). Berisi 60 soal lengkap (180 pernyataan B/S) dari Kelas 1 hingga Kelas 6.',90,60,1),(23,'bank-soal-akbar-buku-smp-mts-60','Bank Soal Akbar Buku Cetak TKA SMP/MTs (60 Soal Komprehensif Kelas 7–9)','SMP/MTs','Bank Soal Akbar Buku (Kelas 7–9) • 60 Soal Matematika, IPA, IPS & AI','Paket spesial pembeli buku cetak SMP/MTs (Kode LINISWARA-SMP2026). Berisi 60 soal TKA lengkap (180 pernyataan B/S) Kelas 7, 8, dan 9.',90,60,1),(24,'bank-soal-akbar-buku-sma-ma-80','Bank Soal Akbar Buku SMART STEPS TKA SMA/MA (80 Soal MIPA, IPS & SNBT)','SMA/MA','Bank Soal Akbar Buku (Kelas 10–12) • 80 Soal Peminatan MIPA, IPS & TPS','Bank soal akbar khusus pembeli buku SMART STEPS SMA/MA (Kode LINISWARA-TKA2025). Berisi 80 soal intensif (240 pernyataan B/S) siap ujian.',120,80,1),(25,'bank-soal-akbar-buku-smk-mak-100','Bank Soal Akbar Buku SMART STEPS TKA SMK/MAK (100 Soal KIK & Semua Jurusan)','SMK/MAK','Bank Soal Akbar Buku (Kelas 10–12) • 100 Soal Teknologi, Bisnis & KIK','Bank soal akbar terlengkap 100 soal (300 pernyataan B/S) untuk pembeli buku cetak SMK/MAK (Kode SMARTSTEPS-SMK) mencakup semua kompetensi kejuruan.',120,100,1);
