  `id` int NOT NULL AUTO_INCREMENT,
  `package_id` int NOT NULL,
  `question_number` int NOT NULL,
  `topic` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stimulus` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `statement_1` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer_1` tinyint(1) NOT NULL,
  `statement_2` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer_2` tinyint(1) NOT NULL,
  `statement_3` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer_3` tinyint(1) NOT NULL,
  `explanation` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `package_id` (`package_id`),
  CONSTRAINT `tryout_questions_ibfk_1` FOREIGN KEY (`package_id`) REFERENCES `tryout_packages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=511 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
