LOCK TABLES `tryout_questions` WRITE;
/*!40000 ALTER TABLE `tryout_questions` DISABLE KEYS */;
INSERT INTO `tryout_questions` VALUES (1,1,1,'Membaca Cerita Anak','Pagi ini Siti dan adik perempuannya yang bernama Lani menanam dua pot bunga matahari di halaman rumah. Setiap hari pukul 07.00 pagi, mereka bergantian menyiram tanaman itu dengan satu gayung air agar tumbuh subur. Dua minggu kemudian, tunas hijau mulai muncul dari dalam tanah.','Siti menanam bunga matahari bersama adik perempuannya, Lani.',1,'Mereka menyiram tanaman setiap malam hari pukul 21.00.',0,'Tunas hijau mulai muncul setelah dua minggu disiram setiap pagi.',1,'Pernyataan 1 benar (Siti dan Lani menanam bunga matahari). Pernyataan 2 salah karena mereka menyiram pukul 07.00 pagi, bukan 21.00 malam. Pernyataan 3 benar sesuai kalimat terakhir.'),(2,1,2,'Berhitung Belanja Sekolah','Budi membawa uang Rp20.000,00 ke koperasi sekolah. Ia membeli 2 buah buku tulis seharga Rp4.500,00 per buku dan 1 buah pensil seharga Rp3.000,00. Sisa uangnya ia masukkan ke dalam celengan di rumah.','Harga 2 buah buku tulis yang dibeli Budi adalah Rp9.000,00.',1,'Total seluruh belanjaan Budi di koperasi adalah Rp12.000,00.',1,'Sisa uang kembalian yang dibawa pulang Budi adalah Rp10.000,00.',0,'2 buku × Rp4.500 = Rp9.000 (Benar). Total belanja = Rp9.000 + Rp3.000 = Rp12.000 (Benar). Sisa uang = Rp20.000 - Rp12.000 = Rp8.000, bukan Rp10.000 (Salah).'),(3,1,3,'Mengenal Tumbuhan & Energi','Tumbuhan hijau membuat makanannya sendiri melalui proses fotosintesis pada bagian daun. Untuk melakukan fotosintesis, tumbuhan memerlukan cahaya matahari, air yang diserap akar dari dalam tanah, dan gas karbon dioksida dari udara. Hasil dari proses ini adalah makanan bagi tumbuhan serta gas oksigen yang sangat dibutuhkan manusia untuk bernapas.','Proses pembuatan makanan pada tumbuhan hijau disebut fotosintesis.',1,'Tumbuhan menyerap air dari dalam tanah melalui bagian daunnya.',0,'Salah satu hasil fotosintesis adalah gas oksigen untuk bernapas manusia.',1,'Pernyataan 1 dan 3 sesuai bacaan. Pernyataan 2 salah karena air diserap oleh akar dari dalam tanah, bukan oleh daun.'),(4,1,4,'Pecahan & Pembagian Kue','Ibu memotong sebuah kue bolu menjadi 8 bagian yang sama besar. Rani memakan 2 potong kue, adiknya memakan 3 potong kue, dan sisanya disimpan di dalam kulkas untuk ayah yang pulang bekerja sore nanti.','Bagian kue yang dimakan Rani dapat ditulis sebagai pecahan 2/8 atau 1/4 bagian.',1,'Jumlah kue yang dimakan Rani dan adiknya seluruhnya ada 5 potong.',1,'Sisa kue yang disimpan di kulkas untuk ayah ada 4 potong.',0,'Rani makan 2/8 = 1/4 (Benar). Total dimakan = 2 + 3 = 5 potong (Benar). Sisa kue = 8 - 5 = 3 potong, bukan 4 potong (Salah).'),(5,1,5,'Kebersamaan di Kelas','Setiap hari Jumat pagi, seluruh siswa kelas 5 melaksanakan kegiatan \'Jumat Bersih\' selama 30 menit sebelum pelajaran dimulai. Kelompok 1 bertugas menyapu lantai kelas, kelompok 2 mengelap kaca jendela, dan kelompok 3 merapikan rak buku bacaan di pojok literasi.','Kegiatan Jumat Bersih dilaksanakan setelah jam pulang sekolah.',0,'Lama waktu kegiatan Jumat Bersih adalah setengah jam (30 menit).',1,'Kelompok 3 bertugas merapikan rak buku bacaan di pojok literasi.',1,'Pernyataan 1 salah karena dilaksanakan sebelum pelajaran dimulai. Pernyataan 2 (30 menit = setengah jam) dan pernyataan 3 benar.'),(6,1,6,'Menghitung Waktu Perjalanan','Edo berangkat dari rumah ke sekolah naik sepeda pukul 06.25 pagi. Waktu tempuh perjalanan dari rumah Edo ke sekolah adalah 20 menit. Bel masuk sekolah berbunyi tepat pukul 07.00 pagi.','Edo tiba di halaman sekolah pada pukul 06.45 pagi.',1,'Edo datang terlambat melewati bel masuk sekolah.',0,'Edo masih memiliki waktu 15 menit sebelum bel masuk sekolah berbunyi.',1,'06.25 + 20 menit = 06.45 (Benar). Karena bel pukul 07.00, Edo tidak terlambat (Salah) dan masih punya sisa waktu 15 menit (Benar).'),(7,1,7,'Daur Hidup Hewan','Kupu-kupu mengalami perubahan bentuk tubuh sempurna mulai dari telur, berubah menjadi ulat (larva), kemudian menjadi kepompong (pupa), hingga akhirnya keluar menjadi kupu-kupu dewasa yang bersayap indah. Berbeda dengan kupu-kupu, belalang tidak melewati fase kepompong.','Urutan daur hidup kupu-kupu adalah telur → ulat → kepompong → kupu-kupu dewasa.',1,'Belalang mengalami fase kepompong sebelum menjadi belalang dewasa.',0,'Ulat merupakan salah satu tahapan dalam pertumbuhan kupu-kupu.',1,'Pernyataan 1 dan 3 sesuai bacaan. Pernyataan 2 salah karena teks menegaskan belalang tidak melewati fase kepompong.'),(8,1,8,'Tabel Pengunjung Perpustakaan','Data pengunjung Perpustakaan SD Harapan dalam tiga hari tercatat sebagai berikut: hari Senin sebanyak 32 siswa, hari Selasa sebanyak 45 siswa, dan hari Rabu sebanyak 28 siswa.','Hari dengan jumlah pengunjung terbanyak adalah hari Selasa.',1,'Selisih pengunjung hari Selasa dan hari Rabu adalah 17 siswa.',1,'Total pengunjung selama tiga hari tersebut kurang dari 100 siswa.',0,'Selasa 45 paling banyak (Benar). Selisih Selasa-Rabu = 45 - 28 = 17 (Benar). Total = 32 + 45 + 28 = 105 siswa, lebih dari 100 (Salah).'),(9,1,9,'Menghemat Listrik di Rumah','Mematikan lampu kamar saat siang hari dan mencabut pengisi daya (charger) ponsel ketika baterai sudah penuh adalah kebiasaan baik untuk menghemat energi listrik. Selain menghemat biaya bulanan orang tua, tindakan ini juga membantu menjaga keselamatan rumah dari korsleting.','Membiarkan lampu kamar menyala sepanjang siang termasuk perilaku hemat energi.',0,'Mencabut charger saat baterai penuh dapat membantu menjaga keselamatan dari korsleting.',1,'Menghemat listrik di rumah juga ikut meringankan biaya listrik bulanan.',1,'Pernyataan 1 salah karena justru memboroskan listrik. Pernyataan 2 dan 3 sesuai teks.'),(10,1,10,'Bangun Datar Taman Sekolah','Taman bunga di tengah sekolah berbentuk persegi panjang dengan panjang 8 meter dan lebar 5 meter. Di sekeliling taman akan dipasang pagar kayu kecil, sedangkan di dalamnya ditanami rumput hijau.','Keliling taman bunga berbentuk persegi panjang tersebut adalah 26 meter.',1,'Luas area taman yang ditanami rumput hijau adalah 40 meter persegi.',1,'Jika panjang pagar yang dibutuhkan dihitung dari luas taman, maka diperlukan pagar 40 meter.',0,'Keliling = 2 × (8 + 5) = 26 m (Benar). Luas = 8 × 5 = 40 m² (Benar). Panjang pagar di sekeliling taman menggunakan keliling (26 m), bukan luas (Salah).'),(11,2,1,'Katalog & Literasi Buku SMP','Pada pembelajaran Kurikulum Nasional Fase D di SMP/MTs, buku terbitan Liniswara mencakup mata pelajaran inti seperti Matematika, Ilmu Pengetahuan Alam (IPA), Ilmu Pengetahuan Sosial (IPS), Bahasa Indonesia, Bahasa Inggris, hingga Koding dan Kecerdasan Artifisial untuk Kelas 7, 8, dan 9.','Jenjang SMP/MTs pada Kurikulum Nasional berada pada Fase D yang mencakup kelas 7 hingga 9.',1,'Buku Koding dan Kecerdasan Artifisial belum tersedia untuk jenjang SMP/MTs.',0,'Mata pelajaran IPA dan IPS termasuk dalam buku teks inti SMP/MTs Liniswara.',1,'Pernyataan 1 dan 3 sesuai bacaan. Pernyataan 2 salah karena buku Koding dan Kecerdasan Artifisial sudah tersedia untuk SMP/MTs.'),(12,2,2,'Matematika SMP: Perbandingan & Skala','Peta lokasi perpustakaan daerah memiliki skala 1 : 50.000. Jarak antara SMP Negeri 2 Magelang dan perpustakaan daerah pada peta adalah 6 cm. Naufal berangkat naik sepeda dengan kecepatan rata-rata 12 km/jam.','Jarak sebenarnya dari sekolah ke perpustakaan daerah adalah 3 km.',1,'Waktu tempuh Naufal menggunakan sepeda dengan kecepatan 12 km/jam adalah 15 menit.',1,'Jika skala peta diubah menjadi 1 : 100.000, maka jarak pada peta menjadi 12 cm.',0,'Jarak sebenarnya = 6 × 50.000 cm = 300.000 cm = 3 km (Benar). Waktu = 3 km / 12 km/jam = 0,25 jam = 15 menit (Benar). Pada skala 1:100.000, jarak peta justru mengecil menjadi 3 cm (Salah).'),(13,2,3,'Koding & Kecerdasan Artifisial SMP','Dalam berpikir komputasional, masalah kompleks dipecah menjadi bagian kecil (dekomposisi), lalu dicari pola kesamaannya (pengenalan pola), menyaring informasi penting (abstraksi), dan menyusun langkah penyelesaian terurut (algoritma). Keempat pilar ini membantu siswa SMP merancang program komputer maupun melatih model AI sederhana.','Dekomposisi adalah proses memecah masalah besar menjadi bagian-bagian yang lebih kecil.',1,'Abstraksi berarti memasukkan seluruh detail yang tidak relevan ke dalam alur program.',0,'Algoritma berisi langkah-langkah terurut untuk menyelesaikan suatu permasalahan.',1,'Pernyataan 1 dan 3 sesuai definisi pada teks. Abstraksi adalah menyaring informasi penting dan mengabaikan detail tidak relevan (Pernyataan 2 Salah).'),(14,2,4,'IPS SMP: Kegiatan Ekonomi & UMKM','Koperasi siswa SMP memproduksi 80 botol minuman herbal dengan modal total Rp480.000,00. Seluruh botol habis terjual dengan harga Rp8.000,00 per botol. Dari keuntungan bersih yang diperoleh, 25% disisihkan untuk kas kegiatan OSIS.','Total pendapatan kotor penjualan 80 botol minuman adalah Rp640.000,00.',1,'Keuntungan bersih yang diperoleh koperasi siswa adalah Rp180.000,00.',0,'Dana yang disisihkan untuk kas OSIS sebesar Rp40.000,00.',1,'Pendapatan = 80 × 8.000 = Rp640.000 (Benar). Keuntungan = 640.000 - 480.000 = Rp160.000, bukan 180.000 (Salah). Kas OSIS = 25% × 160.000 = Rp40.000 (Benar).'),(15,2,5,'IPA SMP: Suhu & Perubahan Wujud','Air murni pada tekanan 1 atmosfer membeku pada suhu 0°C dan mendidih pada suhu 100°C. Saat air dipanaskan hingga berubah menjadi uap air, proses tersebut disebut menguap dan memerlukan penyerapan kalor (energi panas).','Titik didih air murni pada tekanan 1 atmosfer adalah 100°C.',1,'Perubahan wujud dari cair menjadi gas disebut mengembun.',0,'Proses penguapan air memerlukan penyerapan kalor.',1,'Pernyataan 1 dan 3 benar. Perubahan cair menjadi gas disebut menguap, sedangkan mengembun adalah gas menjadi cair (Pernyataan 2 Salah).'),(16,2,6,'Matematika SMP: Statistika Rata-Rata','Nilai ulangan IPA Dita selama 4 kali berturut-turut adalah 78, 82, 86, dan 90. Untuk memperoleh nilai rapor rata-rata minimal 85, Dita masih harus mengikuti 1 kali ulangan harian ke-5.','Rata-rata nilai Dita dari 4 ulangan pertama adalah 84.',1,'Jika pada ulangan ke-5 Dita mendapat nilai 89, rata-rata kelima ulangannya tepat 85.',1,'Nilai terendah yang diperoleh Dita selama 4 ulangan pertama adalah 82.',0,'(78+82+86+90)/4 = 336/4 = 84 (Benar). Agar rata-rata 5 ulangan = 85, total harus 425 → nilai ke-5 = 425 - 336 = 89 (Benar). Nilai terendah adalah 78, bukan 82 (Salah).'),(17,2,7,'Bahasa Indonesia SMP: Teks Berita','Perpustakaan daerah Kabupaten Magelang meluncurkan program Pojok Baca Digital pada hari Senin (10/11). Sebanyak 15 sekolah menengah pertama ikut serta menerima akses e-book literasi sains dan buku pengayaan gratis.','Program Pojok Baca Digital diluncurkan pada hari Senin tanggal 10 November.',1,'Seluruh peserta yang menerima akses pada berita tersebut berasal dari jenjang perguruan tinggi.',0,'Unsur \'Siapa\' dan \'Kapan\' dalam berita tersebut terjawab dengan jelas.',1,'Pernyataan 1 dan 3 sesuai unsur 5W+1H berita. Pernyataan 2 salah karena penerimanya adalah 15 sekolah menengah pertama (SMP).'),(18,2,8,'English SMP: School Library Rules','Notice: Students may borrow up to 3 books for 7 days. Please return books on time so other students can read them. Food and drinks are not allowed inside the reading room.','Students can borrow a maximum of 3 books at one time.',1,'The borrowing period for each book is 14 days.',0,'Eating snacks and drinking inside the reading room are prohibited.',1,'Borrowing period is 7 days, not 14 days (Statement 2 False). Statements 1 and 3 match the notice.'),(19,2,9,'Aljabar & Persamaan Linear SMP','Harga 1 buku tulis adalah x rupiah dan harga 1 bolpoin adalah y rupiah. Diketahui harga 2 buku tulis dan 1 bolpoin adalah Rp13.000,00. Jika harga 1 bolpoin adalah Rp3.000,00, maka harga satuan buku tulis dapat ditentukan dengan persamaan linear sederhana.','Persamaan yang mewakili pembelian tersebut adalah 2x + y = 13.000.',1,'Harga 1 buku tulis (nilai x) adalah Rp5.000,00.',1,'Jika membeli 3 buku tulis saja, biaya yang harus dibayar adalah Rp12.000,00.',0,'2x + 3.000 = 13.000 → 2x = 10.000 → x = 5.000 (Pernyataan 1 & 2 Benar). Harga 3 buku = 3 × 5.000 = Rp15.000, bukan 12.000 (Salah).'),(20,2,10,'Penalaran Evaluasi Tryout','Setiap paket simulasi di portal Liniswara memiliki 10 soal dan tiap soal berisi 3 pernyataan Benar/Salah (total 30 pernyataan). Skor akhir dihitung dari (Jumlah Pernyataan Benar / 30) × 100.','Jika siswa menjawab tepat 27 dari 30 pernyataan, skor akhirnya adalah 90,00.',1,'Total seluruh pernyataan yang dinilai dalam 1 paket simulasi adalah 20 pernyataan.',0,'Skor maksimal jika seluruh pernyataan benar adalah 100.',1,'27/30 × 100 = 90 (Benar). Total pernyataan = 10 × 3 = 30 pernyataan, bukan 20 (Salah). 30/30 × 100 = 100 (Benar).'),(21,3,1,'Literasi Informasi Penerbitan','Sejak berdiri pada 2021, PT Lini Suara Nusantara (Liniswara) berkolaborasi dengan 25+ MGMP di Jawa Timur dan Jawa Tengah untuk menerbitkan lebih dari 900 judul buku bagi jenjang SD, SMP, SMA/MA, dan SMK/MAK. Liniswara memperoleh penghargaan dari Perpustakaan Nasional RI (2023) serta Penerbit Terbaik Serah Simpan Karya Cetak Jawa Tengah (2025).','Mitra MGMP Liniswara berjumlah lebih dari 25 kelompok di Jawa Timur dan Jawa Tengah.',1,'Penghargaan Perpustakaan Nasional RI diterima Liniswara pada tahun 2025.',0,'Total karya terbit Liniswara telah melampaui 900 judul buku lintas jenjang.',1,'Penghargaan Perpusnas RI diterima tahun 2023, sedangkan 2025 adalah penghargaan dari Dinas Kearsipan dan Perpustakaan Jawa Tengah (Pernyataan 2 Salah).'),(22,3,2,'Numerasi Pengadaan Buku SMA','Sebuah SMA Negeri memesan 120 eksemplar buku seri Smart Steps: TKA seharga Rp75.000,00 per eksemplar. Karena pembelian melebihi 100 buku, sekolah mendapatkan potongan harga 20% dan buku dikirim merata ke dalam 4 kardus.','Total pembayaran bersih setelah diskon 20% adalah Rp7.200.000,00.',1,'Setiap kardus berisi 25 eksemplar buku.',0,'Potongan harga per buku adalah Rp15.000,00.',1,'Bruto = Rp9.000.000; diskon 20% = Rp1.800.000; netto = Rp7.200.000 (Benar). Isi per kardus = 120/4 = 30 buku (Salah). Diskon per buku = 20% × 75.000 = Rp15.000 (Benar).'),(23,3,3,'Deep Learning & Projek IPAS SMA','Pembelajaran Mendalam (Deep Learning) menekankan tiga pengalaman belajar utama: berkesadaran (mindful), bermakna (meaningful), dan menggembirakan (joyful). Dalam Projek IPAS SMA kelas X, siswa meneliti kualitas air sungai di sekitar sekolah alih-alih sekadar menghafal tabel kimia.','Pendekatan Deep Learning mendorong siswa mengaitkan konsep dengan masalah nyata di sekitar.',1,'Hafalan tabel tanpa praktik lapangan merupakan tujuan utama Projek IPAS pada teks.',0,'Mindful, meaningful, dan joyful merupakan tiga pilar pengalaman belajar yang disebutkan.',1,'Pernyataan 1 dan 3 sesuai bacaan. Pernyataan 2 salah karena teks mengkontraskan praktik penelitian nyata dengan sekadar menghafal.'),(24,3,4,'Numerasi Distribusi Skor TKA','Dari 40 siswa kelas XII SMA yang mengikuti Tryout TKA, 10 siswa meraih skor 85, 16 siswa meraih skor 75, 10 siswa meraih skor 65, dan sisanya meraih skor 55. Batas tuntas ditetapkan pada skor ≥ 70.','Sebanyak 4 siswa meraih skor 55.',1,'Persentase siswa yang tuntas (skor ≥ 70) adalah 65%.',1,'Rata-rata skor seluruh kelas XII tersebut lebih tinggi dari 75.',0,'Siswa skor 55 = 40 - 36 = 4 (Benar). Tuntas = (10+16)/40 = 65% (Benar). Rata-rata = (850+1200+650+220)/40 = 2920/40 = 73 < 75 (Salah).'),(25,3,5,'English Analytical Text','Digital reading platforms help high school students track their weekly progress. However, studies show that combining printed workbooks with online practice simulations leads to higher retention than screen-only reading.','Combining printed workbooks with online simulations improves learning retention compared to screen-only reading.',1,'The text states that printed workbooks are completely useless in the digital era.',0,'Digital platforms allow students to monitor their weekly progress.',1,'Statements 1 and 3 accurately reflect the text; Statement 2 contradicts the benefit of printed workbooks.'),(26,3,6,'Manajemen Waktu Ujian TKA','Ardi mengerjakan 10 soal tryout berdurasi 30 menit. Ia memakai 2 menit 15 detik rata-rata untuk setiap soal nomor 1–8, lalu memakai sisa waktunya untuk nomor 9, 10, dan memeriksa jawaban.','Total waktu untuk soal nomor 1 sampai 8 adalah 18 menit.',1,'Sisa waktu setelah soal nomor 8 selesai adalah 10 menit.',0,'Jika nomor 9 dan 10 masing-masing butuh 3 menit, tersisa 6 menit untuk memeriksa jawaban.',1,'8 × 2,25 = 18 menit (Benar). Sisa = 30 - 18 = 12 menit (Salah). 12 - 6 = 6 menit (Benar).'),(27,3,7,'Keamanan Data & Aplikasi Web','Dalam standar keamanan aplikasi modern, kata sandi di-hash satu arah menggunakan algoritma scrypt atau bcrypt dengan salt acak. Cookie sesi ditandai HttpOnly agar tidak dapat dibaca oleh JavaScript pada sisi peramban.','Hashing satu arah dengan salt mencegah kata sandi asli mudah terbaca saat database bocor.',1,'Penanda HttpOnly membuat cookie sesi bebas dibaca oleh skrip JavaScript pihak ketiga.',0,'Algoritma scrypt dan bcrypt adalah contoh metode hashing kata sandi.',1,'HttpOnly justru memblokir akses JavaScript terhadap cookie sesi (Pernyataan 2 Salah).'),(28,3,8,'Pertumbuhan Pengguna Belajar Daring','Pada Oktober tercatat 400 pengguna aktif platform belajar. Bulan November naik 25% dari Oktober, lalu bulan Desember bertambah lagi 150 siswa dari total November.','Jumlah pengguna aktif pada bulan November adalah 500 siswa.',1,'Total pengguna aktif pada bulan Desember mencapai 650 siswa.',1,'Persentase kenaikan total dari Oktober ke Desember kurang dari 50%.',0,'Nov = 500, Des = 650. Kenaikan Okt–Des = 250/400 = 62,5% > 50% (Pernyataan 3 Salah).'),(29,3,9,'English Academic Integrity','Academic integrity requires students to cite sources properly when writing essays. Plagiarism—copying another author\'s work without attribution—undermines original thinking and violates school ethics.','Citing sources properly is part of maintaining academic integrity.',1,'Copying an author\'s work without credit is encouraged in academic essays.',0,'Plagiarism weakens original thinking and violates school ethics.',1,'Statement 2 contradicts the definition of plagiarism in the text.'),(30,3,10,'Penalaran Skoring Pilihan Ganda Kompleks','Pada format 10 soal × 3 pernyataan B/S, skor akhir = (pernyataan benar / 30) × 100. Soal dikategorikan \'Sempurna\' jika ketiga pernyataannya dijawab tepat.','Menjawab benar 24 dari 30 pernyataan menghasilkan skor 80,00.',1,'Menjawab benar tepat 2 pernyataan di setiap soal menghasilkan 10 Soal Sempurna.',0,'Satu nomor soal memiliki bobot maksimal 3 pernyataan yang dinilai.',1,'Jika hanya 2 dari 3 pernyataan yang benar per soal, tidak ada soal yang sempurna (0 Soal Sempurna).'),(31,4,1,'KIK: Break Even Point (BEP)','Unit produksi Bisnis Digital SMK memproduksi paket merchandise edukasi dengan biaya tetap Rp1.500.000,00 per bulan. Biaya variabel per paket Rp25.000,00 dan harga jual Rp55.000,00 per paket.','Margin kontribusi per paket merchandise adalah Rp30.000,00.',1,'Titik impas (BEP unit) tercapai apabila terjual 50 paket dalam sebulan.',1,'Penjualan sebanyak 40 paket dalam sebulan sudah menghasilkan laba bersih.',0,'Margin = 55.000 - 25.000 = 30.000 (Benar). BEP = 1.500.000 / 30.000 = 50 paket (Benar). Menjual 40 paket masih di bawah BEP (Salah).'),(32,4,2,'Pemasaran Digital: Conversion Rate','Kampanye iklan buku kejuruan SMK mencatat 10.000 tayangan, 500 klik tautan produk, dan 25 transaksi pembelian dengan total biaya iklan Rp500.000,00.','Biaya per klik (Cost Per Click) kampanye tersebut adalah Rp1.000,00.',1,'Tingkat konversi pembelian dari pengklik iklan adalah 10%.',0,'Biaya akuisisi pelanggan (CAC) rata-rata adalah Rp20.000,00 per pembelian.',1,'CPC = 500.000/500 = Rp1.000 (Benar). Conversion = 25/500 = 5%, bukan 10% (Salah). CAC = 500.000/25 = Rp20.000 (Benar).'),(33,4,3,'English Text: Vocational PKL Notice','Announcement for Grade XII SMK: All students in the Industry Internship Program (PKL) must upload their signed logbooks before Friday, December 12 at 15:00 WIB. Verification is conducted jointly by school coordinators and industry mentors.','The logbook submission deadline is Friday, December 12 at 15:00 WIB.',1,'Only industry mentors conduct verification without school coordinators.',0,'Students must ensure their logbooks are signed before uploading.',1,'Verification is conducted jointly by both school coordinators and industry mentors (Statement 2 False).'),(34,4,4,'KIK: Hak Kekayaan Intelektual','Siswa RPL SMK merancang aplikasi kasir UMKM \'WarungPintar\'. Pembimbing menyarankan mendaftarkan kode sumber aplikasi sebagai Hak Cipta serta nama dan logo produk sebagai Merek Dagang resmi.','Kode sumber perangkat lunak dilindungi dalam rezim Hak Cipta.',1,'Nama dan logo produk didaftarkan sebagai Merek Dagang.',1,'Pendaftaran merek hanya diperbolehkan untuk perusahaan besar dan tidak berlaku bagi UMKM.',0,'UMKM dan kreator lokal sangat dianjurkan mendaftarkan merek dagangnya (Pernyataan 3 Salah).'),(35,4,5,'SOP Bengkel Teknik Otomotif','Prosedur keselamatan bengkel mewajibkan teknisi memakai sepatu safety, memeriksa tekanan ban dan sistem rem sebelum uji jalan, serta mencatat seluruh penggantian suku cadang pada work order pelanggan.','Pemakaian sepatu safety merupakan bagian dari prosedur keselamatan bengkel.',1,'Pemeriksaan sistem rem baru dilakukan setelah kendaraan selesai uji jalan.',0,'Penggantian suku cadang wajib dicatat pada dokumen work order pelanggan.',1,'Pemeriksaan sistem rem dilakukan sebelum uji jalan (Pernyataan 2 Salah).'),(36,4,6,'KIK: Business Model Canvas','Pada Business Model Canvas (BMC), blok Value Propositions memetakan nilai manfaat utama yang ditawarkan kepada pelanggan, sedangkan blok Cost Structure merinci seluruh pos biaya operasional usaha.','Value Propositions berfokus pada manfaat solusi yang dirasakan pelanggan.',1,'Cost Structure mencatat rincian biaya operasional bisnis.',1,'Value Propositions dan Cost Structure memiliki fungsi yang identik di BMC.',0,'Keduanya adalah blok berbeda dengan fungsi berbeda pada BMC (Pernyataan 3 Salah).'),(37,4,7,'Akuntansi Dasar Koperasi SMK','Unit usaha koperasi SMK mencatat pemasukan minggu pertama Rp3.200.000,00, biaya bahan Rp1.950.000,00, dan ongkos kirim Rp250.000,00. Sebanyak 50% dari kas bersih disisihkan untuk dana pengembangan produk.','Total pengeluaran unit usaha tersebut adalah Rp2.200.000,00.',1,'Kas bersih sebelum penyisihan adalah Rp1.250.000,00.',0,'Dana yang dialokasikan untuk pengembangan produk sebesar Rp500.000,00.',1,'Pengeluaran = 2.200.000; kas bersih = 1.000.000 (bukan 1.250.000); 50% × 1.000.000 = Rp500.000.'),(38,4,8,'Layanan Tamu Perhotelan SMK','Staf front office hotel wajib menyapa tamu maksimal 3 detik setelah tamu tiba, memverifikasi reservasi, menjelaskan jam sarapan, lalu menyerahkan kartu kunci aktif dalam sampul pelindung.','Staf menyapa tamu paling lama 3 detik setelah kedatangan di meja resepsionis.',1,'Penjelasan jam sarapan disampaikan setelah tamu masuk ke kamar.',0,'Kartu kunci kamar diserahkan dalam keadaan aktif di dalam sampul pelindung.',1,'Jam sarapan dijelaskan di resepsionis sebelum menyerahkan kartu kunci (Pernyataan 2 Salah).'),(39,4,9,'TJKT: Keamanan Jaringan Sekolah','Administrator lab TJKT memisahkan jaringan Wi-Fi tamu dan jaringan server ujian menggunakan VLAN, serta mengganti kata sandi router bawaan pabrik sebelum perangkat dioperasikan.','Pemisahan jaringan tamu dan server ujian dilakukan menggunakan konfigurasi VLAN.',1,'Membiarkan kata sandi router bawaan pabrik aman untuk jaringan produksi.',0,'Penggantian kata sandi bawaan dilakukan sebelum perangkat mulai dioperasikan.',1,'Kata sandi default pabrik sangat rentan dan wajib diganti sebelum operasional (Pernyataan 2 Salah).'),(40,4,10,'Inovasi Produk & Minimum Viable Product','Tim siswa SMK membuat Minimum Viable Product (MVP) untuk diuji coba oleh 30 siswa dan 5 guru MGMP guna mengumpulkan umpan balik mengenai tata letak tombol pada layar ponsel.','MVP dibuat untuk menguji fitur inti kepada pengguna awal demi mendapatkan umpan balik.',1,'Uji coba pada bacaan tersebut tidak melibatkan guru MGMP sama sekali.',0,'Masukan tata letak tombol membantu perbaikan desain responsif ponsel.',1,'Uji coba melibatkan 30 siswa dan 5 guru MGMP (Pernyataan 2 Salah).'),(41,5,1,'Penjumlahan Bilangan (Kelas 1)','Budi memiliki 4 buah pensil warna di atas meja. Ibu lalu membelikan 2 buah pensil warna lagi untuk Budi.','Jumlah seluruh pensil warna milik Budi sekarang adalah 6 buah.',1,'Setelah diberi ibu, pensil warna Budi menjadi 9 buah.',0,'Banyaknya pensil warna tambahan dari ibu adalah 2 buah.',1,'Penjumlahan 4 + 2 = 6 buah (Pernyataan 2 Salah).'),(42,5,2,'Pengurangan Sederhana (Kelas 1)','Di keranjang kelas ada 11 bola kasti. Pak Guru membagikan 4 bola untuk latihan kelompok.','Sisa bola kasti yang masih ada di keranjang berjumlah 7 bola.',1,'Bola di keranjang bertambah menjadi 15 bola.',0,'Sebanyak 4 bola telah dibagikan oleh Pak Guru.',1,'Sisa bola di keranjang adalah 11 - 4 = 7 bola (Pernyataan 2 Salah).'),(43,5,3,'Kosakata & Kebiasaan Pagi (Kelas 1)','Setiap pagi pukul 08.00, Lani bangun tidur, merapikan bantal, lalu sarapan nasi dan telur sebelum berangkat ke SD Harapan.','Lani sarapan sebelum berangkat ke sekolah.',1,'Kebiasaan tersebut dilakukan Lani pada pukul 12 malam.',0,'Lani ikut merapikan tempat tidurnya di pagi hari.',1,'Kegiatan merapikan bantal dan sarapan dilakukan pukul 08.00 pagi (Pernyataan 2 Salah).'),(44,5,4,'Penjumlahan Bilangan (Kelas 1)','Edo memiliki 7 buah buah apel di atas meja. Ibu lalu membelikan 5 buah buah apel lagi untuk Edo.','Jumlah seluruh buah apel milik Edo sekarang adalah 12 buah.',1,'Setelah diberi ibu, buah apel Edo menjadi 15 buah.',0,'Banyaknya buah apel tambahan dari ibu adalah 5 buah.',1,'Penjumlahan 7 + 5 = 12 buah (Pernyataan 2 Salah).'),(45,5,5,'Pengurangan Sederhana (Kelas 1)','Di keranjang kelas ada 14 bola kasti. Pak Guru membagikan 4 bola untuk latihan kelompok.','Sisa bola kasti yang masih ada di keranjang berjumlah 10 bola.',1,'Bola di keranjang bertambah menjadi 18 bola.',0,'Sebanyak 4 bola telah dibagikan oleh Pak Guru.',1,'Sisa bola di keranjang adalah 14 - 4 = 10 bola (Pernyataan 2 Salah).'),(46,5,6,'Kosakata & Kebiasaan Pagi (Kelas 1)','Setiap pagi pukul 08.00, Farhan bangun tidur, merapikan bantal, lalu sarapan nasi dan telur sebelum berangkat ke SD Harapan.','Farhan sarapan sebelum berangkat ke sekolah.',1,'Kebiasaan tersebut dilakukan Farhan pada pukul 12 malam.',0,'Farhan ikut merapikan tempat tidurnya di pagi hari.',1,'Kegiatan merapikan bantal dan sarapan dilakukan pukul 08.00 pagi (Pernyataan 2 Salah).'),(47,5,7,'Penjumlahan Bilangan (Kelas 1)','Nadia memiliki 4 buah tas sekolah di atas meja. Ibu lalu membelikan 4 buah tas sekolah lagi untuk Nadia.','Jumlah seluruh tas sekolah milik Nadia sekarang adalah 8 buah.',1,'Setelah diberi ibu, tas sekolah Nadia menjadi 11 buah.',0,'Banyaknya tas sekolah tambahan dari ibu adalah 4 buah.',1,'Penjumlahan 4 + 4 = 8 buah (Pernyataan 2 Salah).'),(48,5,8,'Pengurangan Sederhana (Kelas 1)','Di keranjang kelas ada 12 bola kasti. Pak Guru membagikan 4 bola untuk latihan kelompok.','Sisa bola kasti yang masih ada di keranjang berjumlah 8 bola.',1,'Bola di keranjang bertambah menjadi 16 bola.',0,'Sebanyak 4 bola telah dibagikan oleh Pak Guru.',1,'Sisa bola di keranjang adalah 12 - 4 = 8 bola (Pernyataan 2 Salah).'),(49,5,9,'Kosakata & Kebiasaan Pagi (Kelas 1)','Setiap pagi pukul 08.00, Tari bangun tidur, merapikan bantal, lalu sarapan nasi dan telur sebelum berangkat ke SD Harapan.','Tari sarapan sebelum berangkat ke sekolah.',1,'Kebiasaan tersebut dilakukan Tari pada pukul 12 malam.',0,'Tari ikut merapikan tempat tidurnya di pagi hari.',1,'Kegiatan merapikan bantal dan sarapan dilakukan pukul 08.00 pagi (Pernyataan 2 Salah).'),(50,5,10,'Penjumlahan Bilangan (Kelas 1)','Gilang memiliki 7 buah kotak susu di atas meja. Ibu lalu membelikan 3 buah kotak susu lagi untuk Gilang.','Jumlah seluruh kotak susu milik Gilang sekarang adalah 10 buah.',1,'Setelah diberi ibu, kotak susu Gilang menjadi 13 buah.',0,'Banyaknya kotak susu tambahan dari ibu adalah 3 buah.',1,'Penjumlahan 7 + 3 = 10 buah (Pernyataan 2 Salah).'),(51,6,1,'Perkalian Dasar & Uang (Kelas 2)','Budi membeli 3 bungkus permen jahe. Setiap bungkus berisi 4 butir permen yang sama banyak.','Bentuk perkalian untuk menghitung total permen adalah 3 × 4.',1,'Jumlah seluruh permen Budi adalah 12 butir.',1,'Jika hanya 1 bungkus dibuka, permennya berisi 6 butir.',0,'Total permen = 3 × 4 = 12; 1 bungkus berisi tepat 4 butir (Pernyataan 3 Salah).'),(52,6,2,'Nilai Uang Rupiah (Kelas 2)','Di koperasi sekolah, harga 1 roti cokelat Rp3.000 dan 1 buku gambar Rp4.000. Siti membayar dengan 1 lembar uang Rp10.000.','Total harga kedua barang belanjaan Siti adalah Rp7.000.',1,'Uang kembalian yang harus diterima Siti adalah Rp3.000.',1,'Uang Rp10.000 tidak cukup untuk membeli kedua barang tersebut.',0,'Total belanja Rp7.000 < Rp10.000 sehingga masih ada kembalian Rp3.000 (Pernyataan 3 Salah).'),(53,6,3,'Perkalian Dasar & Uang (Kelas 2)','Lani membeli 5 bungkus permen jahe. Setiap bungkus berisi 6 butir permen yang sama banyak.','Bentuk perkalian untuk menghitung total permen adalah 5 × 6.',1,'Jumlah seluruh permen Lani adalah 30 butir.',1,'Jika hanya 1 bungkus dibuka, permennya berisi 8 butir.',0,'Total permen = 5 × 6 = 30; 1 bungkus berisi tepat 6 butir (Pernyataan 3 Salah).'),(54,6,4,'Nilai Uang Rupiah (Kelas 2)','Di koperasi sekolah, harga 1 penggaris Rp2.000 dan 1 buku gambar Rp4.000. Edo membayar dengan 1 lembar uang Rp10.000.','Total harga kedua barang belanjaan Edo adalah Rp6.000.',1,'Uang kembalian yang harus diterima Edo adalah Rp4.000.',1,'Uang Rp10.000 tidak cukup untuk membeli kedua barang tersebut.',0,'Total belanja Rp6.000 < Rp10.000 sehingga masih ada kembalian Rp4.000 (Pernyataan 3 Salah).'),(55,6,5,'Perkalian Dasar & Uang (Kelas 2)','Dira membeli 3 bungkus permen jahe. Setiap bungkus berisi 8 butir permen yang sama banyak.','Bentuk perkalian untuk menghitung total permen adalah 3 × 8.',1,'Jumlah seluruh permen Dira adalah 24 butir.',1,'Jika hanya 1 bungkus dibuka, permennya berisi 10 butir.',0,'Total permen = 3 × 8 = 24; 1 bungkus berisi tepat 8 butir (Pernyataan 3 Salah).'),(56,6,6,'Nilai Uang Rupiah (Kelas 2)','Di koperasi sekolah, harga 1 tas sekolah Rp4.000 dan 1 buku gambar Rp4.000. Farhan membayar dengan 1 lembar uang Rp10.000.','Total harga kedua barang belanjaan Farhan adalah Rp8.000.',1,'Uang kembalian yang harus diterima Farhan adalah Rp2.000.',1,'Uang Rp10.000 tidak cukup untuk membeli kedua barang tersebut.',0,'Total belanja Rp8.000 < Rp10.000 sehingga masih ada kembalian Rp2.000 (Pernyataan 3 Salah).'),(57,6,7,'Perkalian Dasar & Uang (Kelas 2)','Nadia membeli 5 bungkus permen jahe. Setiap bungkus berisi 5 butir permen yang sama banyak.','Bentuk perkalian untuk menghitung total permen adalah 5 × 5.',1,'Jumlah seluruh permen Nadia adalah 25 butir.',1,'Jika hanya 1 bungkus dibuka, permennya berisi 7 butir.',0,'Total permen = 5 × 5 = 25; 1 bungkus berisi tepat 5 butir (Pernyataan 3 Salah).'),(58,6,8,'Nilai Uang Rupiah (Kelas 2)','Di koperasi sekolah, harga 1 pensil warna Rp3.000 dan 1 buku gambar Rp4.000. Raka membayar dengan 1 lembar uang Rp10.000.','Total harga kedua barang belanjaan Raka adalah Rp7.000.',1,'Uang kembalian yang harus diterima Raka adalah Rp3.000.',1,'Uang Rp10.000 tidak cukup untuk membeli kedua barang tersebut.',0,'Total belanja Rp7.000 < Rp10.000 sehingga masih ada kembalian Rp3.000 (Pernyataan 3 Salah).'),(59,6,9,'Perkalian Dasar & Uang (Kelas 2)','Tari membeli 3 bungkus permen jahe. Setiap bungkus berisi 7 butir permen yang sama banyak.','Bentuk perkalian untuk menghitung total permen adalah 3 × 7.',1,'Jumlah seluruh permen Tari adalah 21 butir.',1,'Jika hanya 1 bungkus dibuka, permennya berisi 9 butir.',0,'Total permen = 3 × 7 = 21; 1 bungkus berisi tepat 7 butir (Pernyataan 3 Salah).'),(60,6,10,'Nilai Uang Rupiah (Kelas 2)','Di koperasi sekolah, harga 1 roti cokelat Rp2.000 dan 1 buku gambar Rp4.000. Gilang membayar dengan 1 lembar uang Rp10.000.','Total harga kedua barang belanjaan Gilang adalah Rp6.000.',1,'Uang kembalian yang harus diterima Gilang adalah Rp4.000.',1,'Uang Rp10.000 tidak cukup untuk membeli kedua barang tersebut.',0,'Total belanja Rp6.000 < Rp10.000 sehingga masih ada kembalian Rp4.000 (Pernyataan 3 Salah).'),(61,7,1,'Satuan Panjang Meter & Sentimeter (Kelas 3)','Pita merah milik Budi panjangnya 2 meter. Sebagian pita sepanjang 40 cm digunakan untuk menghias kado ulang tahun.','Panjang awal pita merah sama dengan 200 sentimeter (cm).',1,'Sisa pita merah yang belum dipakai adalah 160 cm.',1,'Satu meter sama panjangnya dengan 10 sentimeter.',0,'1 meter = 100 cm sehingga 2 m = 200 cm dan sisanya 160 cm (Pernyataan 3 Salah).'),(62,7,2,'Pecahan & Siklus Makhluk Hidup (Kelas 3)','Ibu memotong 1 loyang kue bolu menjadi 5 bagian sama besar untuk Siti dan adik. Di halaman rumah, mereka juga mengamati metamorfosis kupu-kupu dari ulat hingga menjadi kepompong.','Setiap 1 potong kue bolu bernilai pecahan 1/5.',1,'Dalam siklus hidup kupu-kupu, ulat berubah menjadi kepompong sebelum menjadi kupu-kupu dewasa.',1,'Semakin banyak potongan sama besar pada 1 kue utuh, ukuran tiap potongan semakin besar.',0,'Semakin banyak pembagian pada 1 kue utuh, ukuran tiap potongannya justru semakin kecil (Pernyataan 3 Salah).'),(63,7,3,'Satuan Panjang Meter & Sentimeter (Kelas 3)','Pita merah milik Lani panjangnya 4 meter. Sebagian pita sepanjang 60 cm digunakan untuk menghias kado ulang tahun.','Panjang awal pita merah sama dengan 400 sentimeter (cm).',1,'Sisa pita merah yang belum dipakai adalah 340 cm.',1,'Satu meter sama panjangnya dengan 10 sentimeter.',0,'1 meter = 100 cm sehingga 4 m = 400 cm dan sisanya 340 cm (Pernyataan 3 Salah).'),(64,7,4,'Pecahan & Siklus Makhluk Hidup (Kelas 3)','Ibu memotong 1 loyang kue bolu menjadi 7 bagian sama besar untuk Edo dan adik. Di halaman rumah, mereka juga mengamati metamorfosis kupu-kupu dari ulat hingga menjadi kepompong.','Setiap 1 potong kue bolu bernilai pecahan 1/7.',1,'Dalam siklus hidup kupu-kupu, ulat berubah menjadi kepompong sebelum menjadi kupu-kupu dewasa.',1,'Semakin banyak potongan sama besar pada 1 kue utuh, ukuran tiap potongan semakin besar.',0,'Semakin banyak pembagian pada 1 kue utuh, ukuran tiap potongannya justru semakin kecil (Pernyataan 3 Salah).'),(65,7,5,'Satuan Panjang Meter & Sentimeter (Kelas 3)','Pita merah milik Dira panjangnya 2 meter. Sebagian pita sepanjang 50 cm digunakan untuk menghias kado ulang tahun.','Panjang awal pita merah sama dengan 200 sentimeter (cm).',1,'Sisa pita merah yang belum dipakai adalah 150 cm.',1,'Satu meter sama panjangnya dengan 10 sentimeter.',0,'1 meter = 100 cm sehingga 2 m = 200 cm dan sisanya 150 cm (Pernyataan 3 Salah).'),(66,7,6,'Pecahan & Siklus Makhluk Hidup (Kelas 3)','Ibu memotong 1 loyang kue bolu menjadi 5 bagian sama besar untuk Farhan dan adik. Di halaman rumah, mereka juga mengamati metamorfosis kupu-kupu dari ulat hingga menjadi kepompong.','Setiap 1 potong kue bolu bernilai pecahan 1/5.',1,'Dalam siklus hidup kupu-kupu, ulat berubah menjadi kepompong sebelum menjadi kupu-kupu dewasa.',1,'Semakin banyak potongan sama besar pada 1 kue utuh, ukuran tiap potongan semakin besar.',0,'Semakin banyak pembagian pada 1 kue utuh, ukuran tiap potongannya justru semakin kecil (Pernyataan 3 Salah).'),(67,7,7,'Satuan Panjang Meter & Sentimeter (Kelas 3)','Pita merah milik Nadia panjangnya 4 meter. Sebagian pita sepanjang 40 cm digunakan untuk menghias kado ulang tahun.','Panjang awal pita merah sama dengan 400 sentimeter (cm).',1,'Sisa pita merah yang belum dipakai adalah 360 cm.',1,'Satu meter sama panjangnya dengan 10 sentimeter.',0,'1 meter = 100 cm sehingga 4 m = 400 cm dan sisanya 360 cm (Pernyataan 3 Salah).'),(68,7,8,'Pecahan & Siklus Makhluk Hidup (Kelas 3)','Ibu memotong 1 loyang kue bolu menjadi 7 bagian sama besar untuk Raka dan adik. Di halaman rumah, mereka juga mengamati metamorfosis kupu-kupu da